update public.institutions set
  feedback_summary_student = 'Единственный муниципальный вуз Урала творческой направленности: студенты отмечают насыщенную событиями и проектами атмосферу, увлечённых своим делом преподавателей-наставников и востребованность направлений вроде цифрового искусства. Из критики встречаются жалобы на проблемы с дипломами, отдельных преподавателей с унижающим отношением к студентам и расхождение заявленной программы с реальной.',
