update public.institutions set
  feedback_summary_student = 'Единственный театральный вуз Уральского региона, входит в число сильнейших театральных школ России наряду с московскими и петербургскими. Студенты и отраслевые источники отмечают сильный преподавательский состав (около 100 педагогов, включая известных актёров и кандидатов наук) и то, что порядка 80% работников театров Свердловской области — выпускники этого вуза. Развёрнутой критики в открытых источниках найти не удалось, отзывы преимущественно нейтрально-справочные.',
  feedback_positive_highlights = '{"сильный преподавательский состав из практикующих деятелей театра","подавляющее большинство театров региона укомплектовано выпускниками"}',
