  feedback_positive_highlights = '{"индивидуальный подход к обучению","гибкая помесячная оплата","активная научная работа и студенческие конференции"}',
  feedback_negative_highlights = '{"заметный отсев студентов по ряду программ","отдельные скучные лекции и предвзятость на экзаменах"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Гуманитарный университет' and city = 'Екатеринбург';

